"""Native Boolean learned-layer arithmetic, correlated outputs and explicit costs."""
import json,csv
import numpy as np
from .boolean_layer import OUT,sha

def main():
    p=json.loads((OUT/'protocol.json').read_text());m=json.loads((OUT/'manifest.json').read_text());audit=json.loads((OUT/'evidence_audit.json').read_text());assert audit['passed'] and audit['producer_manifest_sha256']==sha(OUT/'manifest.json');rows=[]
    for t in p['samples']:
        cases=[v for v in m['rows'] if v['T']==t];and_mse=np.array([v['estimators']['AND']['observed_sampling_MSE'] for v in cases]);matched=np.array([v['estimators']['matched_float']['observed_sampling_MSE'] for v in cases]);requested=np.array([v['estimators']['requested_float']['observed_target_MSE'] for v in cases]);ratio=np.log(and_mse/matched);extra=np.mean([v['predicted_extra_activation_variance'] for v in cases]);rows.append({'T':t,'geometric_AND_over_matched_float_MSE':float(np.exp(ratio.mean())),'AND_sampling_MSE_mean':float(and_mse.mean()),'matched_float_sampling_MSE_mean':float(matched.mean()),'AND_target_MSE_mean':float(np.mean([v['estimators']['AND']['observed_target_MSE'] for v in cases])),'requested_float_target_MSE_mean':float(requested.mean()),'predicted_extra_activation_variance_mean':float(extra),'native_node_updates_all5models':5*1000*t*2560})
    with (OUT/'summary.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
    text=['# Learned layer using native p-bit AND operations and integer counts','','This tests the full64x32 first layer of five existing positive-weight MNIST models on the first8 consumed validation inputs. Every weight is a stationary probability, without signed-weight range metadata. Every activation is also programmed as a probability. Finite8-bit fields[-4,4] leave all2560 nodes free, including requested endpoints. At each official THRML step, the observer computes Boolean activation AND weight and accumulates integer output counts. A temporal division and deterministic bias are applied on the host afterward. The sampler still uses floating-point bias arithmetic internally; no physical AND/popcount circuit, energy, latency or task-accuracy result is measured.','','## Independent checks','',f'All25 model/sample conditions have1000 Monte Carlo trials (five seeds x200). A separate public THRML raw-state sampler reproduces every **{audit["integer_count_elements_reproduced_exactly"]:,}** saved AND and weight integer count exactly. All mean/variance/covariance/resource calculations are independently checked. Every coordinate mean satisfies the predeclared family-level Bernstein bound. Production **{m["native_node_updates"]:,}** scheduled updates; independent replay **{audit["independent_public_native_node_updates"]:,}**. Requested inputs and actual programmed probabilities remain separate. No labels or task scores were used.','','## Sampling variance cost','','The matched control uses the same sampled weight trajectory but deterministic programmed activation means, reconstructed in F64 from saved weight counts. It is an analytical same-draw control, not another executed native floating-activation layer or a hardware benchmark. For independent Bernoulli weight W and activation A, the extra per-output variance is sum_i p_w,i p_a,i(1-p_a,i)/T. It is nonnegative. This captures additional noise introduced by replacing deterministic activations with p-bits.','','| T | Geometric AND/matched sampling MSE | AND sampling MSE (mean over5 models) | Matched sampling MSE | Extra variance predicted |','|---:|---:|---:|---:|---:|']
    for row in rows:text.append(f'| {row["T"]} | {row["geometric_AND_over_matched_float_MSE"]:.5f} | {row["AND_sampling_MSE_mean"]:.8g} | {row["matched_float_sampling_MSE_mean"]:.8g} | {row["predicted_extra_activation_variance_mean"]:.8g} |')
    text+=['','The desired-weight/input target and the programmed expectation can differ under finite control precision and endpoint clipping. Raw metadata separately reports both sampling MSE and target MSE for AND, programmed-activation and requested-activation controls; all25 conditions and five seed summaries are retained. No favorable stochastic run is selected.','','## Shared activations correlate outputs','','Even though device states are independent, a shared activation stream produces covariance between outputs o!=v: sum_i p_w,io p_w,iv p_a,i(1-p_a,i)/T. The theory and measured covariance of all32 outputs for the first selected input are saved for every case. This is readout correlation caused by sharing, not physical cross-device coupling. It must be accounted for in any future classification-margin/whole-network analysis. The present study executes no ReLU or second layer and supplies no new classifier accuracy.','','## Resource implications','','There are2048 logical weight nodes and512 activation nodes for eight concurrent64-feature input vectors:2560 total,25% more than weight nodes alone. One input at a time would require64 activation nodes but changes concurrency/weight-sharing assumptions. Activation controls change with the input; their programming cost cannot be amortized like static learned weights. The implementation also retains diagnostic weight counts that a standalone AND readout need not keep. Integer accumulators, readout conversion, deterministic biases, eight-bit control settings, dynamic states and physical drivers are distinct costs. Logical Boolean terms are not measured executed instructions or chip energy.','','This establishes an actual Boolean accumulation path through the official simulator for a learned layer, while exposing extra activation variance and output covariance. It does not establish efficient full-network execution or disprove Extropic. The separate Transformer student comparison and its earlier gates remain unchanged. The broad goal remains active.'];report=OUT.parent/'BOOLEAN_LAYER_REPORT.md';report.write_text('\n'.join(text)+'\n')
    import matplotlib;matplotlib.use('Agg');import matplotlib.pyplot as plt
    covariance=np.load(OUT/'model0_T64_covariance.npz');fig,axes=plt.subplots(1,2,figsize=(9,4),layout='constrained');maximum=max(np.max(np.abs(covariance['theory'])),np.max(np.abs(covariance['observed'])))
    for ax,name in zip(axes,['theory','observed']):
        im=ax.imshow(covariance[name],vmin=-maximum,vmax=maximum,cmap='coolwarm');ax.set(title=f'Shared activation output covariance: {name}',xlabel='Output index',ylabel='Output index');fig.colorbar(im,ax=ax)
    fig.savefig(OUT.parent/'boolean_layer_covariance.png',dpi=180);plt.close(fig);print(report)
if __name__=='__main__':main()
